import{z as B,x as i,o as l,c as p,q as s,j as n,D as t,d as E,s as o,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"采样与草图统计","description":"","frontmatter":{"title":"采样与草图统计","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/db-sampling-sketches.md","filePath":"cs/db-sampling-sketches.md","lastUpdated":1791063341000}'),d={name:"cs/db-sampling-sketches.md"};function D(m,a,h,c,T,u){const r=i("Mermaid");return l(),p("div",null,[a[2]||(a[2]=s('<h1 id="采样与草图统计" tabindex="-1">采样与草图统计 <a class="header-anchor" href="#采样与草图统计" aria-label="Permalink to &quot;采样与草图统计&quot;">​</a></h1><div class="epigraph"><p>目录里的直方图会过期；采样与草图用可控误差再看一眼数据，给优化器另一份基数输入。</p><footer>—— 据 Olken and Rotem 对数据库采样；Haas et al.；HyperLogLog 在 NDV；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/cardinality-error-propagation">上一课</a>指出独立假设连乘会炸。本课不重推误差公式。缺口是统计怎么来：全表扫描维护精确 NDV 太贵；过期 ANALYZE 比错误公式更常见。采样（行样本、块样本）与草图（概率结构）在精度、CPU、存储之间折中。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>COUNT(DISTINCT)</code> 与连接 NDV 需要不同值个数。精确维护每个列每个组合不可能。缺口是估计器：均匀行采样在聚簇数据上偏倚；块采样便宜但方差大。草图：HyperLogLog 估 NDV，Count-Min 估频率，quantile sketch 估分位以建直方图。这些结构在计算机课已作为数据流出现；本课只把它们接到优化器目录。</p><p><span class="marginnote">草图可以想成只记「要点」的小纸条：不抄全一亿个用户名，只维护一个几 KB 的小结构，就能报出「大约有多少个不同值」。代价是答案带误差条，而且只能回答设计时就定好的那一类问题。</span></p><p>动态采样：优化时扫一小份数据估当前谓词选择率，适合参数化查询与过期统计。代价是优化时间变长——与计划缓存的「跳过优化」相反。</p><p><span class="marginnote">Olken 的数据库采样综述。HLL 见 Flajolet et al.。本课不把草图当查询结果（近似查询另册），只当优化器输入。计算机栏的 HyperLogLog 课已有算法，这里不重推散列。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>ANALYZE：按块或行取样，建直方图、最频繁值、NULL 比例、NDV 草图。多列：对查询里常见列组维护联合统计或列组 NDV。动态采样：对单次查询的谓词在表上抽若干块。</p><p>样本大小决定置信：选择率极低的谓词（「选一个主键」）样本里可能零命中，要用平滑或改走索引统计。这是估计器偏差，不是存储 bug。</p><p><span class="marginnote">数字实例：表 1 亿行，某值只出现 100 次（选择率百万分之一）。抽 1 万行的样本里期望命中只有 0.0001 个——大概率零命中，优化器便以为「几乎没有这种行」而选错计划。值越稀有，样本越不可信。</span></p>',12)),(l(),n(A,null,{default:t(()=>[o(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%9F%BA%E8%A1%A8%22%5D%20--%3E%20SMP%5B%22%E8%A1%8C%20%2F%20%E5%9D%97%E9%87%87%E6%A0%B7%22%5D%0A%20%20T%20--%3E%20SK%5B%22NDV%20%2F%20%E9%A2%91%E7%8E%87%E8%8D%89%E5%9B%BE%22%5D%0A%20%20SMP%20--%3E%20HIST%5B%22%E7%9B%B4%E6%96%B9%E5%9B%BE%E6%A1%B6%22%5D%0A%20%20SK%20--%3E%20CAT%5B%22%E7%9B%AE%E5%BD%95%E7%BB%9F%E8%AE%A1%22%5D%0A%20%20HIST%20--%3E%20CAT%0A%20%20CAT%20--%3E%20OPT%5B%22%E4%BB%A3%E4%BB%B7%E4%B8%8E%20DP%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("统计是快照：写入一秒钟后样本过期。自动 ANALYZE 阈值（表改了百分之几）是工程。锁定计划的预编译语句在统计刷新后应失效——"),e("a",{href:"/cs/prepared-plan-cache"},"计划缓存"),E(" 已要求。")],-1)),a[5]||(a[5]=e("p",null,"草图有可合并性：分区表各分区一份 HLL，可并成全表 NDV，服务后课分区裁剪与全局估计。",-1)),a[6]||(a[6]=e("p",null,"统计怎么过期、又被刷新回来：",-1)),(l(),n(A,null,{default:t(()=>[o(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%E5%85%A5%E4%B8%8E%E5%88%A0%E9%99%A4%E6%8C%81%E7%BB%AD%E5%8F%91%E7%94%9F%22%5D%20--%3E%20DRIFT%5B%22%E6%A0%B7%E6%9C%AC%E4%B8%8E%E7%9B%B4%E6%96%B9%E5%9B%BE%E6%85%A2%E6%85%A2%E5%A4%B1%E7%9C%9F%22%5D%0A%20%20DRIFT%20--%3E%20TH%5B%22%E6%94%B9%E5%8A%A8%E6%AF%94%E4%BE%8B%E8%B6%8A%E8%BF%87%20ANALYZE%20%E9%98%88%E5%80%BC%22%5D%0A%20%20TH%20--%3E%20RE%5B%22%E9%87%8D%E6%96%B0%E9%87%87%E6%A0%B7%E5%BB%BA%E5%87%BA%E6%96%B0%E7%BB%9F%E8%AE%A1%22%5D%0A%20%20RE%20--%3E%20INV%5B%22%E4%BE%9D%E8%B5%96%E6%97%A7%E7%BB%9F%E8%AE%A1%E7%9A%84%E8%AE%A1%E5%88%92%E7%BC%93%E5%AD%98%E5%A4%B1%E6%95%88%22%5D%0A%20%20INV%20--%3E%20NP%5B%22%E4%B8%8B%E4%B8%80%E6%9D%A1%E6%9F%A5%E8%AF%A2%E6%8C%89%E6%96%B0%E7%BB%9F%E8%AE%A1%E9%80%89%E8%AE%A1%E5%88%92%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">「可合并性」翻译过来就是：部分之和能用固定的并运算拼出来。每个分区各记一张 HLL 小纸条，最后按位取最大合并成全表 NDV——原始数据从头到尾不用凑到一台机器上，这正是它能在分区表上做全局估计的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不校准代价公式里的随机 I/O 常数——下一课代价模型校准。也不把采样查询（<code>TABLESAMPLE</code>）的用户语义与优化器内部采样混成同一 API。近似聚合查询是分析课，不是优化器统计。</p><p>后课默认：统计来自样本与草图，带误差条；极低选择率不要信样本零命中。校准课把「模型常数」与「基数输入」分开调。</p><p>优化器读的是摘要，不是每次优化全表。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>采样与草图维护 NDV、频率、直方图，误差可控但非零。</li><li>动态采样用优化时间换较新的选择率。</li><li>代价模型校准下一课：同样基数下，I/O 与 CPU 权重仍可能错。</li><li>出处：Olken and Rotem；Haas 等；Flajolet 等 HLL；Ramakrishnan and Gehrke。</li></ul>',7))])}const L=B(d,[["render",D]]);export{f as __pageData,L as default};
